#![cfg_attr(not(test), no_std)]

extern crate alloc;
extern crate self as wasmi_runtime;

pub mod error;
pub mod program;
pub mod runtime;

// Re-exported so that code generated by `#[wasm_host_function]` can name wasmi
// types without downstream crates depending on wasmi directly.
pub use wasmi;
pub use wasmi_runtime_macros::wasm_host_function;

pub use error::{Error, Result};

/// Re-exports used by code generated by `#[wasm_host_function]`. Not a public
/// API; downstream crates should not rely on these items.
#[doc(hidden)]
pub mod __private {
    pub use alloc::boxed::Box;
    pub use alloc::string::ToString;
    pub use alloc::vec;
    pub use alloc::vec::Vec;
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::program::{Program, ProgramConfig};
    use crate::runtime::{RuntimeConfig, WasmHostFunction, WasmRuntime};
    use crate::wasm_host_function;

    #[test]
    fn wasm_program_returns_1337() {
        // Minimal WASM module:
        //   (module (func (export "program") (result i64) i64.const 1337))
        const WAT: &str = "(module (func (export \"program\") (result i64) i64.const 1337))";

        let runtime = WasmRuntime::new(&RuntimeConfig::default(), vec![]).expect("init runtime");
        let mut program_bytes = wat::parse_str(WAT).expect("parse WAT");

        let mut program = Program::new(
            &runtime,
            &mut program_bytes,
            &ProgramConfig::default(),
            Box::new(()),
        )
        .expect("load module");
        assert_eq!(program.call().expect("call program"), 1337);
    }

    #[test]
    fn host_function_macro_registers_and_is_callable_from_wasm() {
        const WAT: &str = r#"(module
            (import "env" "add" (func (param i64 i64) (result i64)))
            (func (export "program") (result i64)
                i64.const 3
                i64.const 4
                call 0))"#;

        #[wasm_host_function]
        fn add(a: i64, b: i64) -> i64 {
            a + b
        }

        let host_functions: Vec<WasmHostFunction> = vec![add_host_function()];
        let runtime =
            WasmRuntime::new(&RuntimeConfig::default(), host_functions).expect("init runtime");
        let mut program_bytes = wat::parse_str(WAT).expect("parse WAT");

        let mut program = Program::new(
            &runtime,
            &mut program_bytes,
            &ProgramConfig::default(),
            Box::new(()),
        )
        .expect("load module");
        assert_eq!(program.call().expect("call program"), 7);
    }

    #[test]
    fn host_function_slice_argument_receives_correct_length() {
        const WAT: &str = r#"(module
            (import "env" "sum" (func (param i32 i32) (result i64)))
            (memory (export "memory") 1)
            (data (i32.const 0) "hello")
            (func (export "program") (result i64)
                i32.const 0
                i32.const 5
                call 0))"#;

        #[wasm_host_function]
        fn sum(data: &[u8]) -> i64 {
            data.iter().map(|byte| i64::from(*byte)).sum()
        }

        let host_functions: Vec<WasmHostFunction> = vec![sum_host_function()];
        let runtime =
            WasmRuntime::new(&RuntimeConfig::default(), host_functions).expect("init runtime");
        let mut program_bytes = wat::parse_str(WAT).expect("parse WAT");

        let mut program = Program::new(
            &runtime,
            &mut program_bytes,
            &ProgramConfig::default(),
            Box::new(()),
        )
        .expect("load module");
        assert_eq!(program.call().expect("call program"), 532);
    }

    #[test]
    fn host_function_mutable_slice_argument_writes_through() {
        const WAT: &str = r#"(module
            (import "env" "fill" (func (param i32 i32 i32)))
            (memory (export "memory") 1)
            (func (export "program") (result i64)
                i32.const 0
                i32.const 4
                i32.const 42
                call 0
                i32.const 0
                i32.load8_u
                i64.extend_i32_u))"#;

        #[wasm_host_function]
        fn fill(data: &mut [u8], value: u32) {
            for byte in data.iter_mut() {
                *byte = value as u8;
            }
        }

        let host_functions: Vec<WasmHostFunction> = vec![fill_host_function()];
        let runtime =
            WasmRuntime::new(&RuntimeConfig::default(), host_functions).expect("init runtime");
        let mut program_bytes = wat::parse_str(WAT).expect("parse WAT");

        let mut program = Program::new(
            &runtime,
            &mut program_bytes,
            &ProgramConfig::default(),
            Box::new(()),
        )
        .expect("load module");
        assert_eq!(program.call().expect("call program"), 42);
    }

    #[test]
    fn host_function_receives_user_data() {
        const WAT: &str = r#"(module
            (import "env" "get_identity" (func (param i64) (result i64)))
            (func (export "program") (result i64)
                i64.const 0
                call 0))"#;

        #[wasm_host_function]
        fn get_identity(ctx: Option<&u32>, unused: i64) -> i64 {
            let _ = unused;
            i64::from(*ctx.unwrap_or(&0))
        }

        let host_functions: Vec<WasmHostFunction> = vec![get_identity_host_function()];
        let runtime =
            WasmRuntime::new(&RuntimeConfig::default(), host_functions).expect("init runtime");
        let mut program_bytes = wat::parse_str(WAT).expect("parse WAT");

        let mut program = Program::new(
            &runtime,
            &mut program_bytes,
            &ProgramConfig::default(),
            Box::new(7u32),
        )
        .expect("load module");
        assert_eq!(program.call().expect("call program"), 7);
        // Host side can inspect the same payload.
        assert_eq!(program.user_data::<u32>(), Some(&7));
    }

    #[test]
    fn host_function_user_data_type_mismatch_is_none() {
        const WAT: &str = r#"(module
            (import "env" "get_identity" (func (param i64) (result i64)))
            (func (export "program") (result i64)
                i64.const 0
                call 0))"#;

        #[wasm_host_function]
        fn get_identity(ctx: Option<&u32>, unused: i64) -> i64 {
            let _ = unused;
            i64::from(*ctx.unwrap_or(&0))
        }

        let host_functions: Vec<WasmHostFunction> = vec![get_identity_host_function()];
        let runtime =
            WasmRuntime::new(&RuntimeConfig::default(), host_functions).expect("init runtime");
        let mut program_bytes = wat::parse_str(WAT).expect("parse WAT");

        // Installed payload is `u64`, but the host function asks for `u32`.
        // The checked downcast must deny rather than reinterpret.
        let mut program = Program::new(
            &runtime,
            &mut program_bytes,
            &ProgramConfig::default(),
            Box::new(7u64),
        )
        .expect("load module");
        assert_eq!(program.call().expect("call program"), 0);
        assert_eq!(program.user_data::<u32>(), None);
        assert_eq!(program.user_data::<u64>(), Some(&7));
    }

    #[test]
    fn program_runs_out_of_fuel() {
        // A loop that never terminates on its own.
        const WAT: &str = r#"(module
            (func (export "program") (result i64)
                (loop $l
                    br $l)
                i64.const 0))"#;

        let runtime = WasmRuntime::new(&RuntimeConfig::default(), vec![]).expect("init runtime");
        let mut program_bytes = wat::parse_str(WAT).expect("parse WAT");
        let config = ProgramConfig {
            fuel: 100_000,
            ..ProgramConfig::default()
        };

        let mut program =
            Program::new(&runtime, &mut program_bytes, &config, Box::new(())).expect("load module");
        let error = program.call().expect_err("should exhaust fuel");
        assert!(matches!(error, Error::OutOfFuel));
    }
}
